#include "studio.h"

namespace {
constexpr const char* kGlowFs =
    "in vec2 fragTexCoord;\n"
    "in vec4 fragColor;\n"
    "uniform sampler2D texture0;\n"
    "uniform vec4 colDiffuse;\n"
    "uniform float glow;\n"
    "out vec4 finalColor;\n"
    "void main() {\n"
    "  vec4 base = texture(texture0, fragTexCoord) * colDiffuse * fragColor;\n"
    "  finalColor = vec4(base.rgb * (1.0 + glow), base.a);\n"
    "}\n";
Shader glowShader{};
int glowAt = -1;
}  // namespace

void loadGlow() {
  glowShader = studio::shader(nullptr, kGlowFs);
  glowAt = GetShaderLocation(glowShader, "glow");
}

void setGlow(float amount) { SetShaderValue(glowShader, glowAt, &amount, SHADER_UNIFORM_FLOAT); }
